import re, os, subprocess, collections

files=[]
for root,dirs,fs in os.walk('internal'):
    for f in fs:
        if f.endswith('.go') and not f.endswith('_test.go'):
            files.append(os.path.join(root,f))

decls=[]  # (name, path, line, is_method)
funcre=re.compile(r'^func\s+(?:\((?P<recv>[^)]*)\)\s+)?(?P<name>[A-Za-z_][A-Za-z0-9_]*)\s*[\(\[]')
for p in files:
    for i,l in enumerate(open(p, encoding='utf-8', errors='ignore'),1):
        m=funcre.match(l)
        if m:
            decls.append((m.group('name'), p, i, bool(m.group('recv')), (m.group('recv') or '').strip()))

# gather all go files in repo (excluding web)
allgo=[]
for root,dirs,fs in os.walk('.'):
    if any(s in root for s in ('/node_modules','/.git','/web')): continue
    for f in fs:
        if f.endswith('.go'):
            allgo.append(os.path.join(root,f))

contents={p:open(p,encoding='utf-8',errors='ignore').read().splitlines() for p in allgo}

results=[]
for name,p,ln,ismeth,recv in decls:
    pat=re.compile((r'\.' if ismeth else r'\b')+re.escape(name)+r'\s*\(')
    total=0; prod=0; callerfiles=set()
    for cp,lines in contents.items():
        for j,l in enumerate(lines,1):
            if cp==p and j==ln: continue
            if l.lstrip().startswith('//'): continue
            if pat.search(l):
                total+=1
                callerfiles.add(cp)
                if not cp.endswith('_test.go') and '/test/' not in cp: prod+=1
    results.append((total,prod,name,p,ln,ismeth,recv,len(callerfiles)))

results.sort(reverse=True)
for r in results[:25]:
    print(f"{r[0]:5d} total {r[1]:5d} prod  {r[7]:3d} files  {r[2]:30s} {r[3]}:{r[4]} recv={r[6]}")
EOF

