const fs=require("fs"),path=require("path");
const MOD="github.com/usememos/memos";
function walk(d,out){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);
 if(e.isDirectory()){if(["node_modules",".git","web",".codegraph"].includes(e.name))continue;walk(p,out)}
 else if(e.name.endsWith(".go"))out.push(p)}return out}
const all=walk(".",[]).map(p=>p.replace(/^\.\//,""));
const src={};for(const p of all)src[p]=fs.readFileSync(p,"utf8");
// package name per dir
const pkgOf={};
for(const p of all){const m=src[p].match(/^package\s+(\w+)/m); if(m)pkgOf[path.dirname(p)]=m[1];}
// imports per file: map importpath -> alias
function imports(p){const t=src[p];const out={};
 const blk=t.match(/import\s*\(([\s\S]*?)\n\)/);
 const lines=blk?blk[1].split("\n"):(t.match(/^import\s+.*$/gm)||[]).map(s=>s.replace(/^import\s+/,""));
 for(let l of lines){l=l.trim();if(!l||l.startsWith("//"))continue;
  const m=l.match(/^(?:(\w+|\.|_)\s+)?"([^"]+)"/); if(!m)continue;
  out[m[2]]=m[1]||m[2].split("/").pop();}
 return out}
const imp={};for(const p of all)imp[p]=imports(p);
const internal=all.filter(p=>p.startsWith("internal/")&&!p.endsWith("_test.go"));
const funcre=/^func\s+(?:\(([^)]*)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*[\(\[]/;
const decls=[];
for(const p of internal){src[p].split("\n").forEach((l,i)=>{const m=l.match(funcre);
 if(m)decls.push({name:m[2],recv:(m[1]||"").trim(),isM:!!m[1],p,ln:i+1,dir:path.dirname(p)})})}
const res=[];
for(const d of decls){
 const ipath=MOD+"/"+d.dir;
 const esc=d.name.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
 let tot=0,prod=0;const files=new Set();
 for(const p of all){
  const same=path.dirname(p)===d.dir;
  const alias=imp[p][ipath];
  if(!same && !alias) continue;
  let pats=[];
  if(d.isM) pats.push(new RegExp("\\."+esc+"\\s*\\("));
  else { if(same)pats.push(new RegExp("(?<![.\\w])"+esc+"\\s*\\(")); if(alias)pats.push(new RegExp("(?<![.\\w])"+alias.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+"\\."+esc+"\\s*\\(")); }
  const lines=src[p].split("\n");
  for(let j=0;j<lines.length;j++){ if(p===d.p&&j+1===d.ln)continue; const l=lines[j];
   if(l.trim().startsWith("//"))continue;
   if(l.trim().startsWith("func ")&&same&&!d.isM&&new RegExp("^func\\s+"+esc+"\\s*[\\(\\[]").test(l.trim()))continue;
   if(pats.some(r=>r.test(l))){tot++;files.add(p);if(!p.endsWith("_test.go")&&!p.includes("/test/"))prod++}}}
 res.push({...d,tot,prod,files:files.size});
}
res.sort((a,b)=>b.tot-a.tot);
console.log("=== by total ===");
for(const r of res.slice(0,20))console.log(String(r.tot).padStart(4),"tot",String(r.prod).padStart(4),"prod",String(r.files).padStart(3),"files ",r.name.padEnd(24),r.p+":"+r.ln,"recv="+r.recv);
res.sort((a,b)=>b.prod-a.prod);
console.log("=== by prod ===");
for(const r of res.slice(0,20))console.log(String(r.tot).padStart(4),"tot",String(r.prod).padStart(4),"prod",String(r.files).padStart(3),"files ",r.name.padEnd(24),r.p+":"+r.ln,"recv="+r.recv);
'

