const fs=require("fs"),path=require("path");
function walk(d,out){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);
 if(e.isDirectory()){if(["node_modules",".git","web",".codegraph","proto"].includes(e.name))continue;walk(p,out)}
 else if(e.name.endsWith(".go"))out.push(p)}return out}
const all=walk(".",[]).map(p=>p.replace(/^\.\//,""));
const entities=["Memo","User","Attachment","Reaction","Inbox","MemoRelation","MemoShare","UserSetting","InstanceSetting","IdentityProvider","UserIdentity","Shortcut","Store"];
const res={};
for(const e of entities){
 const pkgs=new Set(),files=new Set(),prodPkgs=new Set();let hits=0;
 const re=new RegExp("\\bstore\\."+e+"\\b(?![A-Za-z0-9_])","g");
 for(const p of all){
  if(p.startsWith("store/"))continue;
  const t=fs.readFileSync(p,"utf8");
  const m=t.match(re);
  if(m){hits+=m.length;files.add(p);const d=path.dirname(p);pkgs.add(d);if(!p.endsWith("_test.go")&&!p.includes("/test/"))prodPkgs.add(d);}
 }
 res[e]={hits,pkgs:[...pkgs].sort(),files:files.size,prodPkgs:[...prodPkgs].sort()};
}
const arr=Object.entries(res).sort((a,b)=>b[1].pkgs.length-a[1].pkgs.length||b[1].hits-a[1].hits);
for(const [e,v] of arr)console.log(e.padEnd(18),"pkgs="+String(v.pkgs.length).padStart(2),"prodPkgs="+String(v.prodPkgs.length).padStart(2),"files="+String(v.files).padStart(2),"refs="+String(v.hits).padStart(4),"  ["+v.pkgs.join(", ")+"]");
'

